<template>
 <section class="ndg" :class="{'ndg--approved':approved}" :aria-busy="busy" aria-label="Illustrative Narriva five-check animation">
  <img class="ndg-brand" :src="NARRIVA_BRAND.compliance" alt="Narriva Compliance by AuricWell"/>
  <div class="ndg-orbit" :class="{'ndg-orbit--running':busy}"><span class="ndg-ring" aria-hidden="true"></span><img :src="approved?NARRIVA_BRAND.verified:NARRIVA_BRAND.icon" :alt="approved?'Example approved':'Narriva example check'"/></div>
  <h3>{{ busy?'Checking the example note…':approved?'Example approved.':'Example needs review.' }}</h3><p>{{ busy?`${completed} of 5 approved · showing the next check`:'Illustration only · no AI or compliance service runs' }}</p>
  <ol><li v-for="(check,index) in checks" :key="check.id" :class="`ndg-step--${check.status}`"><span class="ndg-step-state" aria-hidden="true"><span v-if="check.status==='running'" class="ndg-spinner"></span><span v-else>{{ check.status==='passed'?'✓':check.status==='action_required'?'!':index+1 }}</span></span><strong>{{ check.label }}</strong><span class="ndg-label">{{ check.status==='passed'?'Approved':check.status==='running'?'Checking…':check.status==='action_required'?'Review':'Waiting' }}</span></li></ol>
  <div v-if="approved" class="ndg-outcome" role="status"><strong>✓ All 5 example checks approved</strong><span>The prepared SOIP note is ready to review and edit.</span></div>
 </section>
</template>
<script setup>
import {computed} from 'vue';
import {NARRIVA_BRAND,NARRIVA_CHECKS} from '../../config/narrivaBrand.js';
const props=defineProps({review:{type:Object,default:null},busy:Boolean});
const checks=computed(()=>NARRIVA_CHECKS.map(item=>({...item,status:props.review?.checks?.find(c=>c.id===item.id)?.status||'pending'})));
const completed=computed(()=>checks.value.filter(c=>c.status==='passed').length);
const approved=computed(()=>!props.busy&&props.review?.status==='passed'&&completed.value===5);
</script>
<style scoped>
