dding:16px 10px;margin-top:18px;border-radius:9px;background:#e4f4eb;color:#216747;animation:ndg-approved .35s ease-out}.ndg-outcome strong{font-size:13px}.ndg-outcome span{font-size:10px;line-height:1.7}.ndg--approved .ndg-ring{border-color:#67a987}@keyframes ndg-spin{to{transform:rotate(360deg)}}@keyframes ndg-approved{from{opacity:.3;transform:scale(.92)}to{opacity:1;transform:scale(1)}}@media(max-width:500px){.ndg{padding:20px 14px}.ndg li{padding:10px 8px;gap:7px}.ndg h3{font-size:21px}.ndg li strong{font-size:10px}.ndg-label{font-size:8px}}@media(prefers-reduced-motion:reduce){.ndg-ring,.ndg-spinner,.ndg-step-state,.ndg-outcome{animation:none!important}.ndg li{transition:none}}
</style>
